{
  "flashcards": [
    {
      "front": "What is the primary goal of a Staff-level platform engineer when designing for partial failure?",
      "back": "To ensure system resilience through graceful degradation, circuit breaking, and automated recovery, preventing cascading failures across the distributed architecture.",
      "requirement_ids": ["r1", "r2"]
    },
    {
      "front": "How do you define 'scale' in the context of infrastructure engineering?",
      "back": "Scale is not just traffic volume; it is the ability to maintain performance, reliability, and operational cost-efficiency as the system's complexity, data volume, and user base grow orders of magnitude.",
      "requirement_ids": ["r1", "r2"]
    },
    {
      "front": "What is the most critical factor when implementing multi-tenant isolation in Kubernetes?",
      "back": "Ensuring a 'blast radius' containment strategy using namespaces, NetworkPolicies, ResourceQuotas, and PodSecurityAdmission to prevent one tenant from impacting the availability or security of another.",
      "requirement_ids": ["r3", "r5"]
    },
    {
      "front": "Why is 'written communication' a core competency for Staff-level engineers?",
      "back": "Staff engineers must drive consensus across teams. Clear, asynchronous documentation (RFCs, design docs, post-mortems) is the primary tool to align stakeholders, justify technical trade-offs, and scale decision-making without constant meetings.",
      "requirement_ids": ["r4"]
    },
    {
      "front": "What is a 'circuit breaker' pattern and why is it essential for distributed systems?",
      "back": "It prevents an application from repeatedly trying to execute an operation that is likely to fail. It 'trips' to stop requests to a failing service, allowing it time to recover and protecting the calling service from resource exhaustion.",
      "requirement_ids": ["r2"]
    },
    {
      "front": "How do you justify a major infrastructure migration in a written proposal?",
      "back": "Focus on business outcomes: cost reduction, developer velocity, or risk mitigation. Frame the technical debt being addressed as a blocker to these outcomes, and include a clear 'do nothing' scenario analysis.",
      "requirement_ids": ["r1", "r4"]
    },
    {
      "front": "What is the difference between soft and hard multi-tenancy in Kubernetes?",
      "back": "Soft multi-tenancy relies on logical isolation (Namespaces, RBAC) for teams that trust each other. Hard multi-tenancy requires physical or strong isolation (separate clusters, sandboxed runtimes like gVisor) for untrusted workloads or strict compliance requirements.",
      "requirement_ids": ["r3", "r5"]
    },
    {
      "front": "When designing for scale, what is the 'CAP theorem' trade-off?",
      "back": "In the presence of a network partition, a distributed system must choose between Consistency (all nodes see the same data) and Availability (every request receives a response). You cannot have both.",
      "requirement_ids": ["r2"]
    },
    {
      "front": "What is the purpose of a 'Post-Mortem' document?",
      "back": "To create a blameless record of an incident, identifying root causes and systemic weaknesses. It serves as a communication tool to prevent recurrence and educate the wider engineering organization.",
      "requirement_ids": ["r4"]
    },
    {
      "front": "How do you handle 'noisy neighbor' issues in a multi-tenant Kubernetes environment?",
      "back": "Implement strict ResourceQuotas and LimitRanges to cap CPU/memory usage per namespace. Use PriorityClasses and node affinity to ensure critical workloads are not starved by resource-heavy, lower-priority tasks.",
      "requirement_ids": ["r3", "r5"]
    }
  ]
}
